// === Tab: mySketch ===
// by SamuelYAN
// more works //
// ****** // https://twitter.com/SamuelAnn0924
// ****** // https://www.instagram.com/samuel_yan_1990/

// landscape painting 
p5.disableFriendlyErrors = true;

var seed = Math.random() * 1000;
var mySize, margin;
let colorbg = "e3d7a3".split("-").map((a) => "#" + a + "80");
let colorbg2 = "f8f1d3".split("-").map((a) => "#" + a + "80");
let filter, grad;

//moutain
var xOff, yOff;
var color1, color2;
let colorsA = "e3d7a3BF-f5989d33-ea618e40-fce4d6b3-caac7180".split("-").map((a) => "#" + a);
let colorsA2 = "e3d7a3-f5989d-ea618e-fce4d6-caac71".split("-").map((a) => "#" + a + "00");
let colorsB = "6cbbd4BF-5863b140-5282a1BF-fee8f733-c1f29b80".split("-").map((a) => "#" + a);
let colorsB2 = "6cbbd4-5863b1-5282a1-fee8f7-c1f29b".split("-").map((a) => "#" + a + "00");
let colorsC = "1b1b1bBF-29292940-f3f3f3BF-222222b3-ff000080".split("-").map((a) => "#" + a);
let colorsC2 = "1b1b1b-292929-f3f3f3-222222-ff0000".split("-").map((a) => "#" + a + "00");
let colorsD = "70c1b3BF-aaf0d340-50514f33-ffe066b3-247ba080".split("-").map((a) => "#" + a);
let colorsD2 = "70c1b3-aaf0d3-50514f-ffe066-247ba0".split("-").map((a) => "#" + a + "00");
let colorsE = "3c1642BF-38637540-08637533-b2ff9eb3-1dd3b080".split("-").map((a) => "#" + a);
let colorsE2 = "3c1642-386375-086375-b2ff9e-1dd3b0".split("-").map((a) => "#" + a + "00");
let colorbgA = "ffffff".split("-").map((a) => "#" + a);
let colorbgA2 = "ffffff07".split("-").map((a) => "#" + a);

//river
let colorsR = "7fdeea-a3b7f0-a1e4f7-6d7db6-5a6696".split("-").map((a) => "#" + a);
let colorsR2 = "7fdeea-a3b7f0-a1e4f7-6d7db6-5a6696".split("-").map((a) => "#" + a + "00");

function setup() {
	// pixelDensity(5);
	mySize = max(windowWidth, windowHeight);
	createCanvas(1112, 834);
	randomSeed(seed);
	color1 = random([colorsA, colorsB, colorsC, colorsD, colorsE]);
	color2 = random([colorsA2, colorsB2, colorsC2, colorsD2, colorsE2]);
	xOff = -100;
	margin = 10;
	background(colorbgA);
	//addWin();
	filter = new makeFilter();
}

function draw() {
	randomSeed(seed);
	background(colorbgA);
	fill(0);
	grad = drawingContext.createLinearGradient(0, 0, 0, height);
	grad.addColorStop(0, colorbg);
	grad.addColorStop(1, colorbg2);
	drawingContext.fillStyle = grad;
	noStroke();
	rectMode(CORNER);
	rect(0, 0, width, height);

	//mountain and river
	noStroke();
	let mountain_h = height / int(random(10, 30));
	for (let n = 0; n < height; n += mountain_h) {
		push();
		translate(0, height - n);

		if (n > height / 3) {
			// mountain
			grad = drawingContext.createLinearGradient(0, -mountain_h, 0, mountain_h);
			grad.addColorStop(0, random(color1));
			grad.addColorStop(1, random(color2));
			drawingContext.fillStyle = grad;
			beginShape();
			curveVertex(-n, n)
			for (let i = xOff; i < width + 100; i += 50) {
				let p = random(-50, 50);
				curveVertex(i, sin(i) * p)
			}
			curveVertex(width + n, n)
			endShape(CLOSE);
		} else {
			//river
			grad = drawingContext.createLinearGradient(0, -mountain_h, 0, mountain_h);
			grad.addColorStop(0, random(colorsR));
			grad.addColorStop(1, random(colorsR2));
			drawingContext.fillStyle = grad;
			beginShape();
			curveVertex(-n, n)
			for (let i = xOff; i < width - xOff; i += 200) {
				var p = random(-1, 1);
				curveVertex(i, cos(i) * p * random(50));
			}
			curveVertex(width + n, n)
			endShape(CLOSE);
		}
		pop();
	}

	//frame
	noFill();
	let colors_frames = "be132d-980f24-af011c-800000-730d0d".split("-").map((a) => "#" + a);
	stroke(random(colors_frames));
	strokeWeight(margin * 1);
	rectMode(CENTER);
	rect(width / 2, height / 2, width, height);
	image(overAllTexture, 0, 0);
	// noLoop();
}

function makeFilter() {
	// noiseのフィルターをつくる
	colorMode(HSB, 360, 100, 100, 100);
	drawingContext.shadowColor = color(48, 33, 76, 10);
	overAllTexture = createGraphics(windowWidth, windowHeight);
	overAllTexture.loadPixels();
	for (var i = 0; i < windowWidth; i++) {
		for (var j = 0; j < windowHeight; j++) {
			overAllTexture.set(
				i,
				j,
				color(
					48,
					13,
					86,
					noise(i / 3, j / 3, (i * j) / 10) * random(55, 75)
				)
			);
		}
	}
	overAllTexture.updatePixels();
}

// save jpg
let lapse = 0;    // mouse timer
function mousePressed(){
  if (millis() - lapse > 400){
    save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg"); 
    lapse = millis();
  } 
}

